const adminUsers = `-- name: AdminUsers :many

SELECT u.id, u.kind, u.role, u.username, u.display_name, u.email, u.lang, u.level, u.xp,
       u.created_at, u.last_seen_at, u.expires_at,
       COALESCE(s.islamic_only, false) AS islamic_only,
       (SELECT count(*) FROM user_domains ud WHERE ud.user_id = u.id)::int AS domains,
       COALESCE(p.games, 0)::int AS games,
       CASE WHEN COALESCE(p.answered, 0) > 0
            THEN (p.correct * 100 / p.answered)::int ELSE -1 END AS accuracy,
       COALESCE(sa.kind::text, '')::text AS sanction,
       CASE
         WHEN sa.kind = 'ban' THEN 'banned'
         WHEN sa.kind = 'suspension' THEN 'suspended'
         WHEN u.kind = 'member' AND u.last_seen_at IS NULL THEN 'invited'
         ELSE 'active'
       END::text AS status
FROM users u
LEFT JOIN user_settings s ON s.user_id = u.id
LEFT JOIN LATERAL (
  SELECT (SELECT count(*) FROM game_players gp JOIN games g ON g.id = gp.game_id
          WHERE gp.user_id = u.id AND g.status = 'finished')::int AS games,
         (SELECT count(*) FILTER (WHERE ga.is_correct) FROM game_answers ga
          JOIN game_players gp ON gp.id = ga.player_id WHERE gp.user_id = u.id)::int AS correct,
         (SELECT count(*) FROM game_answers ga
          JOIN game_players gp ON gp.id = ga.player_id WHERE gp.user_id = u.id)::int AS answered
) p ON true
LEFT JOIN LATERAL (
  SELECT x.kind FROM user_sanctions x
  WHERE x.user_id = u.id AND x.lifted_at IS NULL AND (x.until IS NULL OR x.until > now())
  ORDER BY x.created_at DESC LIMIT 1
) sa ON true
WHERE ($1::text = '' OR u.kind::text = $1)
  AND ($2::text = '' OR ($2 = 'staff') = (u.role <> 'player'))
  AND ($3::text = '' OR u.lang = $3)
  AND ($4::text = '' OR $4 = CASE
         WHEN sa.kind = 'ban' THEN 'banned'
         WHEN sa.kind = 'suspension' THEN 'suspended'
         WHEN u.kind = 'member' AND u.last_seen_at IS NULL THEN 'invited'
         ELSE 'active' END)
  AND ($5::text = '' OR u.display_name ILIKE '%' || $5 || '%' OR u.username ILIKE '%' || $5 || '%' OR u.email ILIKE '%' || $5 || '%')
ORDER BY
  CASE WHEN $6::text = 'user'      AND $7::bool THEN lower(u.display_name) END ASC,
  CASE WHEN $6 = 'user'      AND NOT $7 THEN lower(u.display_name) END DESC,
  CASE WHEN $6 = 'role'      AND $7 THEN u.role::text END ASC,
  CASE WHEN $6 = 'role'      AND NOT $7 THEN u.role::text END DESC,
  CASE WHEN $6 = 'games'     AND $7 THEN COALESCE(p.games, 0) END ASC,
  CASE WHEN $6 = 'games'     AND NOT $7 THEN COALESCE(p.games, 0) END DESC,
  CASE WHEN $6 = 'accuracy'  AND $7 THEN CASE WHEN COALESCE(p.answered,0) > 0 THEN p.correct * 100 / p.answered ELSE -1 END END ASC,
  CASE WHEN $6 = 'accuracy'  AND NOT $7 THEN CASE WHEN COALESCE(p.answered,0) > 0 THEN p.correct * 100 / p.answered ELSE -1 END END DESC,
  CASE WHEN $6 = 'last_seen' AND $7 THEN u.last_seen_at END ASC NULLS FIRST,
  CASE WHEN $6 = 'last_seen' AND NOT $7 THEN u.last_seen_at END DESC NULLS LAST,
  u.created_at DESC
LIMIT $9 OFFSET $8
`

