const categoryPerformance = `-- name: CategoryPerformance :many
SELECT c.id, COALESCE(ct.name, ctf.name) AS name, c.color, c.icon, c.question_count,
       COALESCE(sum(s.answered), 0)::int AS answered,
       CASE WHEN COALESCE(sum(s.answered), 0) = 0 THEN 0
            ELSE round(100.0 * sum(s.correct) / sum(s.answered))::int END AS accuracy
FROM categories c
LEFT JOIN category_translations ct  ON ct.category_id = c.id AND ct.lang = $1
LEFT JOIN category_translations ctf ON ctf.category_id = c.id AND ctf.lang = 'en'
LEFT JOIN user_category_stats s ON s.category_id = c.id
GROUP BY c.id, ct.name, ctf.name
ORDER BY answered DESC, c.position
LIMIT $2
`

type CategoryPerformanceParams struct {
	Lang string `json:"lang"`
	Lim  int32  `json:"lim"`
}

type CategoryPerformanceRow struct {
	ID            int64  `json:"id"`
	Name          string `json:"name"`
	Color         string `json:"color"`
	Icon          string `json:"icon"`
	QuestionCount int32  `json:"question_count"`
	Answered      int32  `json:"answered"`
	Accuracy      int32  `json:"accuracy"`
}

// Which categories players find hardest (A01 and A10).
func (q *Queries) CategoryPerformance(ctx context.Context, arg CategoryPerformanceParams) ([]CategoryPerformanceRow, error) {
	rows, err := q.db.Query(ctx, categoryPerformance, arg.Lang, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CategoryPerformanceRow{}
	for rows.Next() {
		var i CategoryPerformanceRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Color,
			&i.Icon,
			&i.QuestionCount,
			&i.Answered,
			&i.Accuracy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

