const countAdminQuestions = `-- name: CountAdminQuestions :one
SELECT count(*) FROM questions q
JOIN categories c ON c.id = q.category_id
JOIN domains d    ON d.id = c.domain_id
LEFT JOIN question_translations t  ON t.question_id = q.id AND t.lang = $1
LEFT JOIN question_translations tm ON tm.question_id = q.id AND tm.lang = q.main_lang
WHERE q.deleted_at IS NULL
  AND ($2::text = '' OR q.status::text = $2)
  AND ($3::bigint = 0 OR d.id = $3)
  AND ($4::bigint = 0 OR c.id = $4)
  AND ($5::int = 0 OR q.difficulty = $5)
  AND ($6::text = '' OR
       ($6 = 'all'     AND (SELECT count(*) FROM question_translations x WHERE x.question_id = q.id) = 3) OR
       ($6 = 'missing' AND (SELECT count(*) FROM question_translations x WHERE x.question_id = q.id) < 3))
  AND ($7::text = '' OR COALESCE(t.body, tm.body) ILIKE '%' || $7 || '%' OR q.id::text = $7)
`

