const ratingSummary = `-- name: RatingSummary :one

SELECT
  count(*)::int AS ratings,
  COALESCE(round(count(*) FILTER (WHERE r.stars >= 3) * 100.0 / NULLIF(count(*), 0)), 0)::int AS positive_percent,
  count(*) FILTER (WHERE r.reason <> '')::int AS reasons_given,
  COALESCE((SELECT r2.reason FROM question_ratings r2
             WHERE r2.reason <> '' AND r2.created_at >= now() - make_interval(days => $1::int)
             GROUP BY r2.reason ORDER BY count(*) DESC, r2.reason LIMIT 1), '')::text AS top_reason,
  COALESCE((SELECT count(*) FROM question_ratings r3
             WHERE r3.reason <> '' AND r3.created_at >= now() - make_interval(days => $1::int)
               AND r3.reason = (SELECT r4.reason FROM question_ratings r4
                                 WHERE r4.reason <> '' AND r4.created_at >= now() - make_interval(days => $1::int)
                                 GROUP BY r4.reason ORDER BY count(*) DESC, r4.reason LIMIT 1)), 0)::int AS top_reason_count
FROM question_ratings r
WHERE r.created_at >= now() - make_interval(days => $1::int)
`

type RatingSummaryRow struct {
	Ratings         int32  `json:"ratings"`
	PositivePercent int32  `json:"positive_percent"`
	ReasonsGiven    int32  `json:"reasons_given"`
	TopReason       string `json:"top_reason"`
	TopReasonCount  int32  `json:"top_reason_count"`
}

// ------------------------------------------------------------------ A09 rated poorly
// A09's three cards, over one window. "Positive" is three stars or more: the player
// screen asks for a thumb, and the bank stores it as stars, so the line is drawn
// where the thumb was.
func (q *Queries) RatingSummary(ctx context.Context, days int32) (RatingSummaryRow, error) {
	row := q.db.QueryRow(ctx, ratingSummary, days)
	var i RatingSummaryRow
	err := row.Scan(
		&i.Ratings,
		&i.PositivePercent,
		&i.ReasonsGiven,
		&i.TopReason,
		&i.TopReasonCount,
	)
	return i, err
}

